func init() {
	Handle("ETC_PTO.C_OPEN_RULE_TIPS", func(s *Session, p *Player, m xym.Msg) {
		id, _ := m["text_id"].(int64)
		text, ok := ruleTips[id]
		if !ok {
			text = "#Y规则说明#n#r· 该玩法的说明暂未整理。"
		}
		s.SendExt("ETC_PTO.S_OPEN_RULE_TIPS", xym.Msg{"text": text})
	})
}
